-- Create SpotifyUsers table for storing linked Spotify accounts per user identifier
-- Create SpotifyPlaylistCaches table for storing cached Spotify playlist metadata
-- Create SpotifyPlaylistCacheTracks table for storing the cached tracks of a playlist

CREATE TABLE "SpotifyUsers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "UserIdentifier" varchar(255) NOT NULL,
    "SpotifyId" varchar(255) NOT NULL,
    "AccessToken" text NOT NULL,
    "RefreshToken" text NOT NULL,
    "LinkedAt" timestamp NOT NULL,
    CONSTRAINT "PK_SpotifyUsers" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_SpotifyUsers_UserIdentifier" UNIQUE ("UserIdentifier"),
    CONSTRAINT "UQ_SpotifyUsers_SpotifyId" UNIQUE ("SpotifyId")
);

CREATE TABLE "SpotifyPlaylistCaches" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "SpotifyUserId" integer NOT NULL,
    "PlaylistId" varchar(255) NOT NULL,
    "SnapshotId" varchar(255) NULL,
    CONSTRAINT "PK_SpotifyPlaylistCaches" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_SpotifyPlaylistCaches_SpotifyUserId_PlaylistId" UNIQUE ("SpotifyUserId", "PlaylistId"),
    CONSTRAINT "FK_SpotifyPlaylistCaches_SpotifyUsers" FOREIGN KEY ("SpotifyUserId")
        REFERENCES "SpotifyUsers" ("Id") ON DELETE CASCADE
);

CREATE TABLE "SpotifyPlaylistCacheTracks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "PlaylistCacheId" integer NOT NULL,
    "TrackId" varchar(255) NOT NULL,
    "AddedAt" timestamp NOT NULL,
    CONSTRAINT "PK_SpotifyPlaylistCacheTracks" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_SpotifyPlaylistCacheTracks_PlaylistCacheId_TrackId" UNIQUE ("PlaylistCacheId", "TrackId"),
    CONSTRAINT "FK_SpotifyPlaylistCacheTracks_SpotifyPlaylistCaches" FOREIGN KEY ("PlaylistCacheId")
        REFERENCES "SpotifyPlaylistCaches" ("Id") ON DELETE CASCADE
);
